"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["23307"],{11489(a){a.exports=JSON.parse('{"id":"FIN-1086","slug":"capacity-utilization","term":"Capacity Utilization","also_known_as":[],"difficulty":"Advanced","definition":"Capacity utilization is the percentage of a business\'s or economy\'s potential output that is actually being produced.","explanation":["Capacity utilization compares actual output with the maximum output possible using existing equipment, buildings and workforce under normal conditions.","For example, a factory that can produce 10,000 units a month but is producing 7,500 has a capacity utilization of 75%.","For a business, higher utilization usually means fixed costs are spread over more units, lowering cost per unit and raising profit. Low utilization can signal weak demand or excess capacity. Very high utilization, close to 100%, can bring strain, such as more breakdowns and overtime costs, and suggests the business may need to invest in more capacity.","For an economy, capacity utilization is an economic indicator. In the United States, the Federal Reserve publishes a monthly measure for industry. High utilization across the economy can signal inflation pressure, as businesses struggle to meet demand, while low utilization suggests spare capacity. Industries such as airlines and hotels track similar measures, such as seat or room occupancy."],"note":"","total":1500,"prev":{"slug":"cannibalization","term":"Cannibalization"},"next":{"slug":"capital-account-balance-of-payments","term":"Capital Account (Balance of Payments)"}}')}}]);